import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let request_uri = request.get("path").unwrap() as! String
        let method = request.get("method").unwrap() as! String

        if is_start_with(request_uri) {
            return true
        }

        switch get_jwt_user(request) {
            case Option.Some(token):
                let user = token.get("user").unwrap() as! HashMap<String, Any>
                if user.get("level").unwrap() as! Int64 > 2 {
                    set_current_user_info_and_log(user)
                    return true
                }
                return false
            case Option.None:
                return false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        let start_with = ["/api", "/login"]
        for s in start_with {
            if request_uri.starts_with(s) {
                return true
            }
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request.get("headers").unwrap() as! HashMap<String, Any>
        let auth = headers.get("Authorization").unwrap() as! HashMap<String, Any>
        let token = auth
        let user = token.get("user").unwrap() as! HashMap<String, Any>

        let jwt = token.get("jwt").unwrap() as! String
        if jwt.starts_with(user.get("name").unwrap() as! String) {
            let name_len = (user.get("name").unwrap() as! String).size()
            let jwt_str_date = jwt.substring(name_len)
            let jwt_date = DateTime.parse(jwt_str_date, "yyyy-MM-dd")
            if DateTime.now().minus(jwt_date).days() >= 3 {
                return Option.None
            }
        }
        return Option.Some(token)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let host = user.get("address").unwrap() as! String
        logging.log(msg: user.get("name").unwrap() as! String + host + DateTime.now().format("yyyy-MM-dd"), level: 1)
    }
}

