import std.collection.*
import std.reflect.*
import std.convert.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let args = command_string.split()
        for (var i = 1; i < args.size; i += 1) {
            let arg = args[i]
            if (arg.startsWith("--")) {
                let key_value = arg.substring(2).split("=")
                if (key_value.size == 2) {
                    arguments.add(key_value[0], convert_type(key_value[0], key_value[1]))
                } else {
                    arguments.add(key_value[0], true)
                }
            } else if (arg.startsWith("-")) {
                let key = arg.substring(1)
                if (i + 1 < args.size && !args[i + 1].startsWith("-")) {
                    arguments.add(key, convert_type(key, args[i + 1]))
                    i += 1
                } else {
                    arguments.add(key, true)
                }
            }
        }
        let missing_args = required.difference(HashSet(arguments.keys()))
        if (!missing_args.isEmpty()) {
            return (false, Some(missing_args))
        }
        return (true, None)
    }

    public func get_argument(key: String): Any {
        arguments.get(key)
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types.add(arg, arg_type)
        if (required) {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        try {
            let typeInfo = types.get(arg)
            if (typeInfo.isEmpty()) {
                return value
            }
            if (typeInfo.get() == TypeInfo.of<Int64>()) {
                return Convert.parseInt64(value).getOrThrow()
            } else if (typeInfo.get() == TypeInfo.of<Float64>()) {
                return Convert.parseFloat64(value).getOrThrow()
            } else if (typeInfo.get() == TypeInfo.of<Bool>()) {
                return Convert.parseBool(value).getOrThrow()
            }
            return value
        } catch {
            return value
        }
    }
}
