            let digit1 = padded1.at(i).toInt()
            let digit2 = padded2.at(i).toInt()
            let sum = digit1 + digit2 + carry
            carry = sum / 10
            let digit = sum % 10
            result.insert(0, digit.toString())
        }

        if (carry > 0) {
            result.insert(0, carry.toString())
        }

        return result.join("")
    }

    public static func subtract(num1: String, num2: String): String {
        var negative = false
        var n1 = num1
        var n2 = num2

        if (num1.length() < num2.length()) {
            n1 = num2
            n2 = num1
            negative = true
        } else if (num1.length() == num2.length()) {
            if (num1 < num2) {
                n1 =num2
                n2 = num1
                negative = true
            }
        }

        let max_length = max(n1.length(), n2.length())
        let padded1 = n1.padStart(max_length, '0')
        let padded2 = n2.padStart(max_length, '0')

        var borrow = 0
        var result = List<String>.empty()

        for (i in (max_length - 1)..0) {
            let digit1 = padded1.at(i).toInt()
            let digit2 = padded2.at(i).toInt()
            var diff = digit1 - digit2 - borrow

            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.insert(0, diff.toString())
        }

        while (result.length() > 1 && result.at(0) == '0') {
            result.remove(0)
        }

        if (negative) {
            result.insert(0, '-')
        }

        return result.join("")
    }

    public static func multiply(num1: String, num2: String): String {
        let len1 = num1.length()
        let len2 = num2.length()
        var result = List<Int64>.filled(len1 + len2, 0)

        for (i in (len1 - 1)..0) {
            for (j in (len2 - 1)..0) {
                let digit1 = num1.at(i).toInt()
                let digit2 = num2.at(j).toInt()
                let product = digit1 * digit2
                let pos1 = i + j
                let pos2 = i + j + 1
                let total = product + result.at(pos2)

                result.set(pos1, result.at(pos1) + total / 10)
                result.set(pos2, total % 10)
            }
        }

        var start = 0
        while (start < result.length() - 1 && result.at(start) == 0) {
            start += 1
        }

        return result.slice(start).map(_.toString()).join("")
    }
