import std.collection.HashMap
import std.convert.RadixConvertible

class BinaryDataProcessor {

    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        this.binary_string = String(binary_string.filter { c => c == '0' || c == '1' })
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        let zeroes_count = binary_string.count { c => c == '0' }
        let ones_count = binary_string.count { c => c == '1' }
        let total_length = binary_string.length.toFloat64()

        let zeroes_percentage = zeroes_count.toFloat64() / total_length
        let ones_percentage = ones_count.toFloat64() / total_length

        let result = HashMap<String, Float64>()
        result.put("Zeroes", zeroes_percentage)
        result.put("Ones", ones_percentage)
        result.put("Bit length", total_length)
        return result
    }

    public func convert_to_ascii(): String {
        var byte_array = Array<UInt8>()
        var i = 0
        while (i < binary_string.length) {
            let byte = binary_string.substring(i, min(i + 8, binary_string.length))
            let decimal = RadixConvertible.binaryToDecimal(byte).toByte()
            byte_array.push(decimal)
            i += 8
        }
        return String.fromAscii(byte_array)
    }

    public func convert_to_utf8(): String {
        var byte_array = Array<UInt8>()
        var i = 0
        while (i < binary_string.length) {
            let byte = binary_string.substring(i, min(i + 8, binary_string.length))
            let decimal = RadixConvertible.binaryToHexadecimal(byte).toByte()
            byte_array.push(decimal)
            i += 8
        }
        return String.fromUtf8(byte_array)
    }
}

