    public func convert_to_utf8(): String {
        var byte_array = Array<UInt8>()
        var i = 0
        while (i < binary_string.length) {
            let byte = binary_string.substring(i, min(i + 8, binary_string.length))
            let decimal = RadixConvertible.binaryToHexadecimal(byte).toByte()
            byte_array.push(decimal)
            i += 8
        }
        return String.fromUtf8(byte_array)
    }
}
