import std.collection.ArrayList

class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        for (i in (this.patLen - 1).downTo(0)) {
            if (char == this.pattern.slice(i, i + 1)) {
                return i
            }
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        for (i in (this.patLen - 1).downTo(0)) {
            if (this.pattern.slice(i, i + 1) != this.text.slice(currentPos + i, currentPos + i + 1)) {
                return currentPos + i
            }
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let positions = ArrayList<Int64>()
        var i: Int64 = 0
        while (i <= this.textLen - this.patLen) {
            let mismatch_index = this.mismatch_in_text(i)
            if (mismatch_index == -1) {
                positions.add(i)
                i += 1
            } else {
                let match_index = this.match_in_pattern(this.text.slice(mismatch_index, mismatch_index + 1))
                let diff = mismatch_index - match_index
                i += if (diff > 1) diff else 1
            }
        }
        return positions
    }
}

