import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        let num_buffer = String()

        for char in expression.chars() {
            if char.isDigit() || char == '.' {
                num_buffer.append(char)
            } else {
                if !num_buffer.isEmpty() {
                    match Float64.parse(num_buffer) {
                        Some(num) => operand_stack.add(num)
                        None => return None
                    }
                    num_buffer.clear()
                }

                if "+-*/^".contains(char) {
                    while (
                        !operator_stack.isEmpty() &&
                        operator_stack[operator_stack.size() - 1] != "(" &&
                        precedence(operator_stack[operator_stack.size() - 1]) >= precedence(char)
                    ) {
                        let (new_operand_stack, new_operator_stack) = apply_operator(operand_stack, operator_stack)
                        operand_stack = new_operand_stack
                        operator_stack = new_operator_stack
                    }
                    operator_stack.add(char.toString())
                } else if char == '(' {
                    operator_stack.add(char.toString())
                } else if char == ')' {
                    while !operator_stack.isEmpty() && operator_stack[operator_stack.size() - 1] != "(" {
                        let (new_operand_stack, new_operator_stack) = apply_operator(operand_stack, operator_stack)
                        operand_stack = new_operand_stack
                        operator_stack = new_operator_stack
                    }
                    if operator_stack.isEmpty() || operator_stack[operator_stack.size() - 1] != "(" {
                        return None
                    }
                    operator_stack.pop()
                }
            }
        }

        if !num_buffer.isEmpty() {
            match Float64.parse(num_buffer) {
                Some(num) => operand_stack.add(num)
                None => return None
            }
        }

        while !operator_stack.isEmpty() {
            let (new_operand_stack, new_operator_stack) = apply_operator(operand_stack, operator_stack)
            operand_stack = new_operand_stack
            operator_stack = new_operator_stack
        }

        if operand_stack.size() == 1 {
            Some(operand_stack[0])
        } else {
            None
        }
    }

    public func precedence(op: String): Int64 {
        let precedences = HashMap<String, Int64>()
        precedences.add("+", 1)
        precedences.add("-", 1)
        precedences.add("*", 2)
        precedences.add("/", 2)
        precedences.add("^", 3)
        match precedences.get(op) {
            Some(p) => p
            None => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        let op = operator_stack.pop()
        let op_func = operators.get(op)
        let operand2 = operand_stack.pop()
        let operand1 = operand_stack.pop()
        let result = op_func(operand1, operand2)
        operand_stack.add(result)
        (operand_stack, operator_stack)
    }
}

