        let remainingParts = parts[1..<parts.size]
        let camelCaseParts = remainingParts.map { part => 
            if (part.size == 0) {
                return part
            }
            return part[0].toUpperCase() + part[1..<part.size].toLowerCase()
        }
        return firstPart + camelCaseParts.join(separator: "")
    }
