import std.collection.ArrayList
import std.time.DateTime

class Course <: Equatable<Course> {
    let name: String
    let start_time: String
    let end_time: String

    public init(name: String, start_time: String, end_time: String) {
        this.name = name
        this.start_time = start_time
        this.end_time = end_time
    }

    public override operator func != (that: Course): Bool {
        return this.name != that.name || this.start_time != that.start_time || this.end_time != that.end_time
    }

    public override operator func == (that: Course): Bool {
        return this.name == that.name && this.start_time == that.start_time && this.end_time == that.end_time
    }
}

class Classroom {
    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        if (!this.courses.contains(course)) {
            this.courses.add(course)
        }
    }

    public func remove_course(course: Course): Unit {
        if (this.courses.contains(course)) {
            this.courses.remove(course)
        }
    }

    public func is_free_at(check_time: String): Bool {
        let checkDateTime = DateTime.parse(check_time, "yyyy/MM/dd HH:mm")
        for (course in this.courses) {
            let startDateTime = DateTime.parse(course.start_time, "yyyy/MM/dd HH:mm")
            let endDateTime = DateTime.parse(course.end_time, "yyyy/MM/dd HH:mm")
            if (startDateTime <= checkDateTime && checkDateTime <= endDateTime) {
                return false
            }
 }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        let newStart = DateTime.parse(new_course.start_time, "yyyy/MM/dd HH:mm")
        let newEnd = DateTime.parse(new_course.end_time, "yyyy/MM/dd HH:mm")
        for (course in this.courses) {
            let start = DateTime.parse(course.start_time, "yyyy/MM/dd HH:mm")
            let end = DateTime.parse(course.end_time, "yyyy/MM/dd HH:mm")
            if (start <= newStart && newStart <= end) {
                return false
            }
            if (start <= newEnd && newEnd <= end) {
                return false
            }
        }
        return true
    }
}

