import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()
        let file = File(Path(file_name), Read)
        let reader = BufferedReader(InputStreamReader(file))
        let line = reader.readLine()
        if (line != null) {
            let fields = line.split(",")
            for (field in fields) {
                title.add(field.trim())
            }
            while (true) {
                let line = reader.readLine()
                if (line == null) {
                    break
                }
                let fields = line.split(",")
                let row = ArrayList<String>()
                for (field in fields) {
                    row.add(field.trim())
                }
                data.add(row)
            }
        }
        file.close()
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = File(Path(file_name), Write)
            let writer = BufferedWriter(OutputStreamWriter(file))
            for (row in data) {
                writer.write(row.join(","))
                writer.newLine()
            }
            writer.flush()
            writer.close()
            file.close()
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        let new_data = ArrayList<ArrayList<String>>()
        new_data.add(title)
        let column_data = ArrayList<String>()
        for (row in data) {
            column_data.add(row.get(N).toUpperCase())
        }
        new_data.add(column_data)
        let new_file_name = Path(save_file_name).fileNameWithoutExtension() + "_process.csv"
        return write_csv(new_data, new_file_name)
    }
}
