import std.sort.sort

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        var sum: Int64 = 0
        for (num in data) {
            sum += num
        }
        return round(sum.toFloat64() / data.size.toFloat64(), 2)
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sortedData = ArrayList<Int64>(data)
        sort(sortedData)
        let n = sortedData.size
        if (n % 2 == 0) {
            let middle = n / 2
            return round((sortedData[middle - 1] + sortedData[middle]).toFloat64() / 2.0, 2)
        } else {
            let middle = n / 2
            return sortedData[middle].toFloat64()
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counter = HashMap<Int64, Int64>()
        for (num in data) {
            if (counter.contains(num)) {
                counter[num] = counter[num] + 1
            } else {
                counter.add(num, 1)
            }
        }
        var modeCount: Int64 = 0
        for (count in counter.values()) {
            if (count > modeCount) {
                modeCount = count
            }
        }
        let result = ArrayList<Int64>()
        for ((num, count) in counter) {
            if (count == modeCount) {
                result.add(num)
            }
        }
        return result
    }
}

