        this.data = data
    }

    public func get_sum(): Float64 {
        var sum: Float64 = 0.0
        for (item in this.data) {
            sum += item
        }
        return sum
    }

    public func get_min(): Float64 {
        var minVal = this.data[0]
        for (item in this.data) {
            if (item < minVal) {
                minVal = item
            }
        }
        return minVal
    }

    public func get_max(): Float64 {
        var maxVal = this.data[0]
        for (item in this.data) {
            if (item > maxVal) {
                maxVal = item
            }
        }
        return maxVal
    }

    public func get_variance(): Float64 {
        let mean = this.get_sum() / this.data.size.toFloat64()
        var variance: Float64 = 0.0
        for (item in this.data) {
            variance += (item - mean) * (item - mean)
        }
        variance /= this.data.size.toFloat64()
        return round(variance, 2)
    }

    public func get_std_deviation(): Float64 {
        let variance = this.get_variance()
        return round(sqrt(variance), 2)
    }

    public func get_correlation(): Float64 {
        if (this.data.size < 2) {
            return 1.0
        }
        let mean = this.get_sum() / this.data.size.toFloat64()
        var covariance: Float64 = 0.0
        var varX: Float64 = 0.0
        var varY: Float64 = 0.0

        for (i in 0..this.data.size) {
            let x = i.toFloat64()
            let y = this.data[i]
            covariance += (x - mean) * (y - mean)
            varX += (x - mean) * (x - mean)
            varY += (y - mean) * (y - mean)
        }
        return covariance / (sqrt(varX) * sqrt(varY))
    }
}
