class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        let mean1 = data1.sum() / Float64(n)
        let mean2 = data2.sum() / Float64(n)

        let numerator = Float64(0.0)
        for i in range(0, n) {
            numerator += (data1.get(i) - mean1) * (data2.get(i) - mean2)
        }

        let denominator1 = Float64(0.0)
        for i in range(0, n) {
            denominator1 += (data1.get(i) - mean1) * (data1.get(i) - mean1)
        }
        let denominator2 = Float64(0.0)
        for i in range(0, n) {
            denominator2 += (data2.get(i) - mean2) * (data2.get(i) - mean2)
        }
        let denominator = sqrt(denominator1) * sqrt(denominator2)

        return denominator != 0.0 ? numerator / denominator : 0.0
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.sum() / Float64(n)
        let variance = Float64(0.0)
        for x in data {
            variance += (x - mean) * (x - mean)
        }
        variance /= Float64(n)
        let std_deviation = sqrt(variance)

        let skewness_numerator = Float64(0.0)
        for x in data {
            skewness_numerator += (x - mean) * (x - mean) * (x - mean)
        }
        skewness_numerator *= Float64(n)
        let skewness_denominator = (Float64(n) - 1.0) * (Float64(n) - 2.0) * std_deviation * std_deviation * std_deviation

        return std_deviation != 0.0 ? skewness_numerator / skewness_denominator : 0.0
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.sum() / Float64(n)
        let std_dev = Float64(0.0)
        for x in data {
            std_dev += (x - mean) * (x - mean)
        }
        std_dev = sqrt(std_dev / Float64(n))

        if std_dev == 0.0 {
            return Float64.nan
        }

        let centered_data = ArrayList<Float64>()
        for x in data {
            centered_data.add(x - mean)
        }
        let fourth_moment = Float64(0.0)
        for x in centered_data {
            fourth_moment += x * x * x * x
        }
        fourth_moment /= Float64(n)

        let kurtosis_value = (fourth_moment / (std_dev * std_dev * std_dev * std_dev)) - 3.0

        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let pdf_values = ArrayList<Float64>()
        let sqrt_two_pi = sqrt(2.0 * 3.141592653589793)
