class DecryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let plaintext = ArrayList<Byte>()
        for char in ciphertext.toBytes() {
            if (char >= 'A'.toByte() && char <= 'Z'.toByte()) {
                let ascii_offset = 'A'.toByte()
                let shifted_char = (char - ascii_offset - shift.toByte()) % 26 + ascii_offset
                plaintext.add(shifted_char)
            } else if (char >= 'a'.toByte() && char <= 'z'.toByte()) {
                let ascii_offset = 'a'.toByte()
                let shifted_char = (char - ascii_offset - shift.toByte()) % 26 + ascii_offset
                plaintext.add(shifted_char)
            } else {
                plaintext.add(char)
            }
        }
        return String.fromBytes(plaintext)
    }

    public func vigenere_decipher(ciphertext: String): String {
        let decrypted_text = ArrayList<Byte>()
        let key_index = 0
        let key_bytes = this.key.toLower().toBytes()
        for char in ciphertext.toBytes() {
            if (char >= 'A'.toByte() && char <= 'Z'.toByte()) {
                let shift = key_bytes[key_index % key_bytes.size()] - 'a'.toByte()
                let decrypted_char = (char - 'A'.toByte() - shift) % 26 + 'A'.toByte()
                decrypted_text.add(decrypted_char)
                key_index += 1
            } else if (char >= 'a'.toByte() && char <= 'z'.toByte()) {
                let shift = key_bytes[key_index % key_bytes.size()] - 'a'.toByte()
                let decrypted_char = (char - 'a'.toByte() - shift) % 26 + 'a'.toByte()
                decrypted_text.add(decrypted_char)
                key_index += 1
            } else {
                decrypted_text.add(char)
            }
        }
        return String.fromBytes(decrypted_text)
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        let fence = ArrayList<ArrayList<Byte>>()
        for i in 0..rails {
            fence.add(ArrayList<Byte>())
            for j in 0..encrypted_text.toBytes().size() {
                fence[i].add('\n'.toByte())
            }
        }
        let direction = -1
        let mut row: Int64 = 0
        let mut col: Int64 = 0

        for i in 0..encrypted_text.toBytes().size() {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }
            fence[row.toInt64()][col] = ' '.toByte()
            col += 1
            row += direction.toInt64()
        }

        let mut index = 0
        for i in 0..rails {
            for j in 0..encrypted_text.toBytes().size() {
                if (fence[i][j] == ' '.toByte()) {
                    fence[i][j] = encrypted_text.toBytes()[index]
                    index += 1
                }
            }
        }

        let mut plain_text = ArrayList<Byte>()
        direction = -1
        row = 0
        col = 0
        for i in 0..encrypted_text.toBytes().size() {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }
            plain_text.add(fence[row.toInt64()][col])
            col += 1
            row += direction.toInt64()
        }
        return String.fromBytes(plain_text)
    }
}

