import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String,	size: Int64): Bool {
        if (!recv.is_full_with_one_more_email(size)) {
            let timestamp = DateTime.now().toString("yyyy-MM-dd HH:mm:ss")
            let email = HashMap<String, Any>([
                ("sender", this.addr),
                ("receiver", recv.addr),
                ("content", content),
                ("size", size),
                ("time", timestamp),
                ("state", "unread")
            ])
            recv.inbox.add(email)
            return true
        } else {
            this.clear_inbox(size)
            return false
        }
    }

    public func fetch(): HashMap<String, Any> {
        if (inbox.size() == 0) {
            return HashMap<String, Any>()
        }
        for (i in 0..inbox.size()) {
            let email = inbox.get(i).getOrThrow()
            if (email.get("state").getOrThrow().toString() == "unread") {
                email.put("state", "read")
                return email
            }
        }
        return HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        let occupied_size = this.get_occupied_size()
        return occupied_size + size > capacity
    }

    public func get_occupied_size(): Int64 {
        var occupied_size: Int64 = 0
        for (email in inbox) {
            occupied_size += email.get("size").getOrThrow().toInt64().getOrThrow()
        }
        return occupied_size
    }

    public func clear_inbox(size: Int64): Unit {
        if (inbox.size() == 0) {
            return
        }
        var freed_space: Int64 = 0
        while (freed_space < size && inbox.size() > 0) {
            let email = inbox.get(0).getOrThrow()
            freed_space += email.get("size").getOrThrow().toInt64().getOrThrow()
            inbox.remove(0)
        }
    }
}

