import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        var ciphertext = ""
        for (char in plaintext.chars()) {
            if (char.isAlpha()) {
                let ascii_offset = if (char.isUpper()) { 65 } else { 97 }
                let shifted_char = Char((char.toInt() - ascii_offset + shift).mod(26) + ascii_offset)
                ciphertext += shifted_char.toString()
            } else {
                ciphertext += char.toString()
            }
        }
        return ciphertext
    }

    public func vigenere_cipherplain_text: String): String {
        var encrypted_text = ""
        var key_index = 0
        for (char in plain_text.chars()) {
            if (char.isAlpha()) {
                let shift = key.chars()[key_index.mod(key.size())].toLower().toInt() - 'a'.toInt()
                let encrypted_char = Char((char.toLower().toInt() - 'a'.toInt() + shift).mod(26) + 'a'.toInt())
                encrypted_text += if (char.isUpper()) { encrypted_char.toUpper().toString() } else { encrypted_char.toString() }
                key_index += 1
            } else {
                encrypted_text += char.toString()
            }
        }
        return encrypted_text
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        let fence = ArrayList<ArrayList<Char>>()
        for (i in 0..rails) {
            fence.add(ArrayList<Char>(plain_text.size(), repeat: '\n'))
        }
        var direction = -1
        var row = 0
        var col = 0

        for (char in plain_text.chars()) {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }

            fence[row][col] = char
            col += 1
            row += direction
        }

        var encrypted_text = ""
        for (i in 0..rails) {
            for (j in 0..plain_text.size()) {
                if (fence[i][j] != '\n') {
                    encrypted_text += fence[i][j].toString()
                }
            }
        }
        return encrypted_text
    }
}

