import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        self.prepare(self.transform(expression))

        let result_stack = ArrayList<String>()
        self.postfix_stack.reverse()

        while (self.postfix_stack.size > 0) {
            let current_op = self.postfix_stack.pop()
            if (!self.is_operator(current_op)) {
                let replaced = current_op.replace("~", "-")
                result_stack.add(replaced)
            } else {
                let second_value = result_stack.pop()
                let first_value = result_stack.pop()

                let first_replaced = first_value.replace("~", "-")
                let second_replaced = second_value.replace("~", "-")

                let temp_result = self._calculate(Decimal(first_replaced), Decimal(second_replaced), current_op)
                result_stack.add(temp_result.toString())
            }
        }

        return Float64(eval(result_stack.join("*")))
    }

    public func prepare(expression: String): Unit {
        let op_stack = ArrayList<String>([","])
        let arr = expression.chars()
        var current_index: Int64 = 0
        var count: Int64 = 0

        for (i, current_op) in arr.enumerate() {
            if (self.is_operator(current_op)) {
                if (count > 0) {
                    self.postfix_stack.add(arr.slice(current_index, current_index + count).join(""))
                }
                let peek_op = op_stack[-1]
                if (current_op == ")") {
                    while (op_stack[-1] != "(") {
                        self.postfix_stack.add(op_stack.pop())
                    }
                    op_stack.pop()
                } else {
                    while (current_op != "(" && peek_op != "," && self.compare(current_op, peek_op)) {
                        self.postfix_stack.add(op_stack.pop())
                        let new_peek = op_stack[-1]
                        if (new_peek == peek_op) {
                            break
                        }
                        peek_op = new_peek
                    }
                    op_stack.add(current_op)
                }

                count = 0
                current_index = i + 1
            } else {
