import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let y_interp = ArrayList<Float64>()
        for xi in x_interp {
            for i in 0..<x.size() - 1 {
                if x[i] <= xi && xi <= x[i+1] {
                    let yi = y[i] + (y[i+1] - y[i]) * (xi - x[i]) / (x[i+1] - x[i])
                    y_interp.push(yi)
                    break
                }
            }
        }
        return y_interp
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let z_interp = ArrayList<Float64>()
        for i in 0..<x_interp.size() {
            let xi = x_interp[i]
            let yi = y_interp[i]
            for j in 0..<x.size() - 1 {
                if x[j] <= xi && xi <= x[j+1] {
                    for k in 0..<y.size() - 1 {
                        if y[k] <= yi && yi <= y[k+1] {
                            let z00 = z[j][k]
                            let z01 = z[j][k+1]
                            let z10 = z[j+1][k]
                            let z11 = z[j+1][k+1]
                            let zi = (z00 * (x[j+1] - xi) * (y[k+1] - yi) +
                                     z10 * (xi - x[j]) * (y[k+1] - yi) +
                                     z01 * (x[j+1] - xi) * (yi - y[k]) +
                                     z11 * (xi - x[j]) * (yi - y[k])) / ((x[j+1] - x[j]) * (y[k+1] - y[k]))
                            z_interp.push(zi)
                            break
                        }
                    }
                    break
                }
            }
        }
        return z_interp
    }
}

