import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var P0: Float64 = 0.0
        for i in 0..k {
            P0 += testData[i][i].toFloat64()
        }
        var xsum = ArrayList<Int64>(repeat: 0, count: k)
        var ysum = ArrayList<Int64>(repeat: 0, count: k)
        var sum: Int64 = 0
        for i in 0..k {
            for j in 0..k {
                xsum[i] += testData[i][j]
                ysum[j] += testData[i][j]
                sum += testData[i][j]
            }
        }
        var Pe: Float64 = 0.0
        for i in 0..k {
            Pe += xsum[i].toFloat64() * ysum[i].toFloat64()
        }
        Pe /= sum.toFloat64() * sum.toFloat64()
        P0 /= sum.toFloat64()
        return (P0 - Pe) / (1 - Pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var sum: Float64 = 0.0
        var P0: Float64 = 0.0
        var ysum = ArrayList<Float64>(repeat: 0.0, count: k)
        for i in 0..N {
            var temp: Floatcast = 0.0
            for j in 0..k {
                sum += testData[i][j].toFloat64()
                ysum[j] += testData[i][j].toFloat64()
                temp += testData[i][j].toFloat64() * testData[i][j].toFloat64()
            }
            temp -= n.toFloat64()
            temp /= (n - 1).toFloat64() * n.toFloat64()
            P0 += temp
        }
        P0 /= N.toFloat64()
        var Pe: Float64 = 0.0
        for i in 0..k {
            Pe += (ysum[i] / sum) * (ysum[i] / sum)
        }
        return (P0 - Pe) / (1 - Pe)
    }
}

