import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        if (!(data is (ArrayList<Int64>, Int64)) && !(data is ArrayList<(ArrayList<Int64>, Int64)>)) {
            throw Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
        }

        if (data is (ArrayList<Int64>, Int64)) {
            let (subList, totalNum) = data as (ArrayList<Int64>, Int64)
            if (totalNum == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            } else {
                let arr = ArrayList<Float64>()
                for (i, t) in subList.enumerated() {
                    if (t == 1) {
                        arr.add(1.0 / Float64(i + 1))
                        break
                    }
                }
                if (arr.size == 0) {
                    return (0.0, ArrayList<Float64>([0.0]))
                }
                return (arr[0], arr)
            }
        } else {
            let dataList = data as ArrayList<(ArrayList<Int64>, Int64)>
            if (dataList.size == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            }
            let separateResult = ArrayList<Float64>()
            for (subList, totalNum) in dataList {
                if (totalNum == 0) {
                    separateResult.add(0.0)
                    continue
                }
                let found = false
                for (i, t) in subList.enumerated() {
                    if (t == 1) {
                        separateResult.add(1.0 / Float64(i + 1))
                        found = true
                        break
                    }
                }
                if (!found) {
                    separateResult.add(0.0)
                }
            }
            let sum = separateResult.fold(0.0, (acc, x) => acc + x)
            return (sum / Float64(separateResult.size), separateResult)
        }
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        if (!(data is (ArrayList<Int64>, Int64)) && !(data is ArrayList<(ArrayList<Int64>, Int64)>)) {
            throw Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
        }

        if (data is (ArrayList<Int64>, Int64)) {
            let (subList, totalNum) = data as (ArrayList<Int64>, Int64)
            if (totalNum == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            } else {
                let rightRankingList = ArrayList<Float64>()
                let count = 1
                for t in subList {
                    if (t == 0) {
                        rightRankingList.add(0.0)
                    } else {
                        rightRankingList.add(Float64(count))
                        count += 1
                    }
                }
                let rankingArray = ArrayList<Float64>()
                for i in 0..subList.size {
                    rankingArray.add(1.0 / Float64(i + 1))
                }
                let sum = 0.0
                for i in 0..rightRankingList.size {
                    sum += rightRankingList[i] * rankingArray[i]
                }
                let ap = sum / Float64(totalNum)
                return (ap, ArrayList<Float64>([ap]))
            }
        } else {
            let dataList = data as ArrayList<(ArrayList<Int64>, Int64)>
            if (dataList.size == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            }
            let separateResult = ArrayList<Float64>()
            for (subList, totalNum) in dataList {
                if (totalNum == 0) {
                    separateResult.add(0.0)
                    continue
                }
                let rightRankingList = ArrayList<Float64>()
                let count = 1
                for t in subList {
                    if (t == 0) {
                        rightRankingList.add(0.0)
                    } else {
                        rightRankingList.add(Float64(count))
                        count += 1
                    }
                }
                let rankingArray = ArrayList<Float64>()
                for i in 0..subList.size {
                    rankingArray.add(1.0 / Float64(i + 1))
                }
                let sum = 0.0
                for i in 0..rightRankingList.size {
                    sum += rightRankingList[i] * rankingArray[i]
                }
                let ap = sum / Float64(totalNum)
                separateResult.add(ap)
            }
            let sum = separateResult.fold(0.0, (acc, x) => acc + x)
            return (sum / Float64(separateResult.size), separateResult)
        }
    }
}

