import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let arr = ArrayList<ArrayList<String>>(n, repeat: ArrayList<String>(n, repeat: "0"))
        let rand = Random()
        var minesPlaced = 0

        while (minesPlaced < k) {
            let x = rand.nextInt64(0, n - 1)
            let y = rand.nextInt64(0, n - 1)
            if (arr[y].get(x) != "X") {
                arr[y].set(x, "X")
                minesPlaced += 1

                for i in max(0, y - 1)..min(n, y + 2) {
                    for j in max(0, x - 1)..min(n, x + 2) {
                        if (arr[i].get(j) != "X") {
                            let current = arr[i].get(j).parseInt64().getOrElse(0)
                            arr[i].set(j, (current + 1).toString())
                        }
                    }
                }
            }
        }
        return arr
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        ArrayList<ArrayList<String>>(n, repeat: ArrayList<String>(n, repeat: "-"))
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for i in 0..n {
            for j in 0..n {
                if (map[i].get(j) == "-" && minesweeper_map[i].get(j) != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (minesweeper_map[x].get(y) == "X") {
            return false
        } else {
            player_map[x].set(y, minesweeper_map[x].get(y))
            score += 1
            if (check_won(player_map)) {
                return true
            }
            return player_map
        }
    }
}

