        let arr = ArrayList<ArrayList<String>>(n, repeat: ArrayList<String>(n, repeat: "0"))
        let rand = Random()
        var minesPlaced = 0

        while (minesPlaced < k) {
            let x = rand.nextInt64(0, n - 1)
            let y = rand.nextInt64(0, n - 1)
            if (arr[y].get(x) != "X") {
                arr[y].set(x, "X")
                minesPlaced += 1

                for i in max(0, y - 1)..min(n, y + 2) {
                    for j in max(0, x - 1)..min(n, x + 2) {
                        if (arr[i].get(j) != "X") {
                            let current = arr[i].get(j).parseInt64().getOrElse(0)
                            arr[i].set(j, (current + 1).toString())
                        }
                    }
                }
            }
        }
        return arr
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        ArrayList<ArrayList<String>>(n, repeat: ArrayList<String>(n, repeat: "-"))
    }

