import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let out = ArrayList<Rune>()
        var pos: Int64 = 0
        let length = string.runeCount()

        while pos < length - 2 {
            let runes = string.runes
            if runes[pos] == '&' && runes[pos + 1] == '#' {
                var start = pos + 2
                var is_hex = false
                let first_char = runes[start]

                if first_char == 'x' || first_char == 'X' {
                    start += 1
                    is_hex = true
                }

                if start == length {
                    return out.toString()
                }

                var end = start
                while end < length && NumericEntityUnescaper.is_hex_char(runes[end]) {
                    end += 1
                }

                if end < length && runes[end] == ';' {
                    let entity_value: String = runes[start..<end].toString()
                    let radix = if is_hex then 16 else 10
                    try {
                        let code = entity_value.toInt64(is_hex)
                        out.add(Rune(code))
                        pos = end + 1
                        continue
                    } catch {
                        return out.toString()
                    }
                }
            }
            let runes = string.runes
            out.add(runes[pos])
            pos += 1
        }

        if pos < length {
            let runes = string.runes
            out.add(runes[pos])
            if pos + 1 < length {
                out.add(runes[pos + 1])
            }
        }

        return out.toString()
    }

    public static func is_hex_char(char: Rune): Bool {
        return char.isDigit() || ('a' <= char.toLower() && char.toLower() <= 'f')
    }
}

