            case None => "*"
            case Some(fields) => fields.join(", ")
        }
        let sql = "SELECT " + fields_str + " FROM " + this.table_name
        condition.match {
            case None => ()
            case Some(cond) => sql += " WHERE " + cond
        }
        return sql + ";"
    }

