import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = sort(data)
        let n = sorted_data.size()
        if n % 2 == 1 {
            return Float64(sorted_data.get(n // 2))
        } else {
            return (Float64(sorted_data.get(n // 2 - 1)) + Float64(sorted_data.get(n // 2))) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for value in data {
            counts.put(value, counts.getOrDefault(value, 0) + 1)
        }
        let max_count = counts.values().max().getOrElse(0)
        let mode_values = ArrayList<Int64>()
        for (value, count) in counts {
            if count == max_count {
                mode_values.add(value)
            }
        }
        return mode_values
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size()
        if n != y.size() || n == 0 {
            return None
        }
        let mean_x = Float64(x.sum()) / Float64(n)
        let mean_y = Float64(y.sum()) / Float64(n)
        let numerator = zip(x, y).map(|(xi, yi)| (Float64(xi) - mean_x) * (Float64(yi) - mean_y)).sum()
        let denominator = sqrt(x.map(|xi| (Float64(xi) - mean_x).pow(2)).sum() * y.map(|yi| (Float64(yi) - mean_y).pow(2)).sum())
        if denominator == 0.0 {
            return None
        }
        return Some(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if data.isEmpty() {
            return None
        }
        return Some(Float64(data.sum()) / Float64(data.size()))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let matrix = ArrayList<ArrayList<Float64>>()
        for i in 0..data.get(0).size() {
            let row = ArrayList<Float64>()
            for j in 0..data.get(0).size() {
                let column1 = data.map(|r| r.get(i))
                let column2 = data.map(|r| r.get(j))
                let correlation = correlation(column1, column2).getOrElse(0.0)
                row.add(correlation)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size()
        if n < 2 {
            return None
        }
        let mean_value = mean(data).getOrElse(0.0)
        let variance = data.map(|x| (Float64(x) - mean_value).pow(2)).sum() / Float64(n - 1)
        return Some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_val = mean(data).getOrElse(0.0)
        let std_deviation = standard_deviation(data).getOrElse(0.0)
        if std_deviation == 0.0 {
            return None
        }
        return Some(data.map(|x| (Float64(x) - mean_val) / std_deviation))
    }
}

