import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        return round(this.taylor(x, 50), 10)
    }

    public func factorial(a: Int64): Decimal {
        var b: Decimal = Decimal.parse("1")
        var c = a
        while c != 1 {
            b *= Decimal.parse(toString(c))
            c -= 1
        }
        return b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var a: Float64 = 1.0
        let radians = x / 180.0 * this.PI
        var count: Int64 = 1
        for k in range(1, n) {
            if count % 2 != 0 {
                a -= pow(radians, Float64(2 * k)) / Float64.parse(toString(this.factorial(2 * k)))
            } else {
                a += pow(radians, Float64(2 * k)) / Float64.parse(toString(this.factorial(2 * k)))
            }
            count += 1
        }
        return a
    }

    public func sin(x: Float64): Float64 {
        let radians = x / 180.0 * this.PI
        var g: Float64 = 0.0
        var t = radians
        var n: Int64 = 1

        while abs(t) >= 1e-15 {
            g += t
            n += 1
            t = -t * radians * radians / Float64(2 * n - 1) / Float64(2 * n - 2)
        }
        return round(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        let cosValue = this.cos(x)
        if abs(cosValue - 0.0) > 0.000001 {
            return Some(this.sin(x) / cosValue)
        } else {
            return None
        }
    }
}

