import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let norm1 = sqrt(vector_1.map(x => x * x).reduce(0.0, (a, b) => a + b))
        let norm2 = sqrt(vector_2.map(x => x * x).reduce(0.0, (a, b) => a + b))
        if norm1 == 0.0 || norm2 == 0.0 {
            return 0.0
        }
        let dot_product = vector_1.zip(vector_2).map((x, y) => x * y).reduce(0.0, (a, b) => a + b)
        return dot_product / (norm1 * norm2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let norm1 = sqrt(vector_1.map(x => x * x).reduce(0.0, (a, b) => a + b))
        let all_norms = vectors_all.map(v => sqrt(v.map(x => x * x).reduce(0.0, (a, b) => a + b)))
        let dot_products = vectors_all.map(v => v.zip(vector_1).map((x, y) => x * y).reduce(0.0, (a, b) => a + b))
        return dot_products.zip(all_norms).map((dp, an) => dp / (norm1 * an))
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if vector_list_1.isEmpty() || vector_list_2.isEmpty() {
            throw ZeroDivisionError("At least one of the passed list is empty.")
        }
        let avg1 = vector_list_1.transpose().map(col => col.reduce(0.0, (a, b) => a + b) / vector_list_1.size().toFloat64())
        let avg2 = vector_list_2.transpose().map(col => col.reduce(0.0, (a, b) => a + b) / vector_list_2.size().toFloat64())
        return VectorUtil.similarity(avg1, avg2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for (key, count) in number_dict {
            result.put(key, log((total_num.toFloat64() + 1.0) / (count + 1.0)))
        }
        return result
    }
}

