import std.collection.HashMap
import std.collection.ArrayList

class Words2Numbers {

    /*
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    */

    let numwords: HashMap<String, Tuple2<Int64, Int64>>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        /*
        Initialize the word lists and dictionaries required for conversion
        */
        this.numwords = HashMap<String, Tuple2<Int64, Int64>>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = Tuple2(1, 0)
        for (idx in 0..this.units.size) {
            this.numwords[this.units[idx]] = Tuple2(1, idx)
        }
        for (idx in 0..this.tens.size) {
            this.numwords[this.tens[idx]] = Tuple2(1, idx * 10)
        }
        for (idx in 0..this.scales.size) {
            if (idx * 3 == 0) {
                this.numwords[this.scales[idx]] = Tuple2(100, 0)
            } else {
                this.numwords[this.scales[idx]] = Tuple2(10 ** (idx * 3), 0)
            }
        }

        this.ordinal_words = HashMap<String, Int64>([
            ("first", 1), ("second", 2), ("third", 3), ("fifth", 5), 
            ("eighth", 8), ("ninth", 9), ("twelfth", 12)
        ])
        this.ordinal_endings = ArrayList<(String, String)>([
            ("ieth", "y"), ("th", "")
        ])
    }

    public func text2int(textnum: String): String {
        let processedText = textnum.replace("-", " ")
        let words = processedText.split()
        var current: Int64 = 0
        var result: Int64 = 0
        var output = ""
        var onNumber = false

        for word in words {
            if this.ordinal_words.contains(word) {
                let value = this.ordinal_words[word]!
                current = current * 1 + value
                onNumber = true
            } else {
                var transformedWord = word
                for (ending, replacement) in this.ordinal_endings {
                    if word.endsWith(ending) {
                        transformedWord = word.substring(0, word.length - ending.length) + replacement
                        break
                    }
                }

                if !this.numwords.contains(transformedWord) {
                    if onNumber {
                        output += (result + current).toString() + " "
                    }
                    output += word + " "
                    result = 0
                    current = 0
                    onNumber = false
                } else {
                    let (scale, increment) = this.numwords[transformedWord]!
                    current = current * scale + increment
                    if scale > 100 {
                        result += current
                        current = 0
                    }
                    onNumber = true
                }
            }
        }

        if onNumber {
            output += (result + current).toString()
        }

        return output.trim()
    }

    public func is_valid_input(textnum: String): Bool {
        let processedText = textnum.replace("-", " ")
        let words = processedText.split()

        for word in words {
            if this.ordinal_words.contains(word) {
                continue
            }

            var transformedWord = word
            var found = false
            for (ending, replacement) in this.ordinal_endings {
                if word.endsWith(ending) {
                    transformedWord = word.substring(0, word.length - ending.length) + replacement
                    found = true
                    break
                }
            }

            if !found && !this.numwords.contains(word) || 
               found && !this.numwords.contains(transformedWord) {
                return false
            }
        }

        return true
    }
}

